    // Leave some padding so text doesn't touch the inner edge
    const centerSize = Math.max(0, innerRadius * 2 - 16);
    // Don't render if there's no inner radius (solid pie, not donut)
    if (innerRadius <= 0) {
        return null;
    }
    // If custom render function is provided, use it
    if (children) {
        return (<div className={cn(chartCenterContainerClassName, "flex items-center justify-center", className)} style={{ width: centerSize, height: centerSize }}>
        {children({
                value: displayValue,
                label: displayLabel,
                isHovered: effectiveHoveredIndex !== null,
                data: hoveredData ?? { label: defaultLabel, value: totalValue },
            })}
      </div>);
    }
    // Default center content with NumberFlow animations
    // Now renders as pure HTML, avoiding Safari's foreignObject bugs
    return (<div className={cn(chartCenterContainerClassName, "flex flex-col items-center justify-center text-center", className)} style={{ width: centerSize, height: centerSize }}>
      <ChartStatFlow formatOptions={formatOptions} label={displayLabel} labelClassName={labelClassName} prefix={prefix} suffix={suffix} value={displayValue} valueClassName={valueClassName}/>
    </div>);
}
