const PieChartCore = memo(function PieChartCore({ width, height, data, innerRadius: innerRadiusProp, padAngle, cornerRadius, startAngle, endAngle, hoverOffset, children, containerRef, hoveredIndexProp, onHoverChange, enterTransition, enterStaggerScale, geometryScrubbing, }: PieChartInnerProps) {
    const [internalHoveredIndex, setInternalHoveredIndex] = useState<number | null>(null);
